-- Reference schema for planning. Room entities/migrations are the implementation source.
PRAGMA foreign_keys = ON;
CREATE TABLE profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, base_currency TEXT NOT NULL, locale_tag TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE accounts (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, type TEXT NOT NULL, currency_code TEXT NOT NULL, opening_balance_minor INTEGER NOT NULL DEFAULT 0, opening_date TEXT NOT NULL, include_in_total INTEGER NOT NULL DEFAULT 1, is_archived INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE categories (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), parent_id TEXT REFERENCES categories(id), name TEXT NOT NULL, kind TEXT NOT NULL, icon_key TEXT, colour_argb INTEGER, is_system INTEGER NOT NULL DEFAULT 0, is_archived INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE merchants (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, normalised_name TEXT NOT NULL, last_used_at INTEGER);
CREATE TABLE recurrence_rules (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), template_transaction_json TEXT NOT NULL, frequency TEXT NOT NULL, interval_count INTEGER NOT NULL DEFAULT 1, days_of_week TEXT, day_of_month INTEGER, invalid_day_policy TEXT, start_local_date TEXT NOT NULL, end_local_date TEXT, max_occurrences INTEGER, posting_mode TEXT NOT NULL, next_run_local_date TEXT, is_paused INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE transactions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), type TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id), to_account_id TEXT REFERENCES accounts(id), category_id TEXT REFERENCES categories(id), merchant_id TEXT REFERENCES merchants(id), amount_minor INTEGER NOT NULL, received_amount_minor INTEGER, currency_code TEXT NOT NULL, transaction_time_utc INTEGER NOT NULL, local_date TEXT NOT NULL, status TEXT NOT NULL, note TEXT, recurrence_rule_id TEXT REFERENCES recurrence_rules(id), recurrence_occurrence_key TEXT UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, CHECK (to_account_id IS NULL OR to_account_id <> account_id));
CREATE TABLE transaction_splits (id TEXT PRIMARY KEY, transaction_id TEXT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, category_id TEXT REFERENCES categories(id), amount_minor INTEGER NOT NULL, note TEXT);
CREATE TABLE tags (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, normalised_name TEXT NOT NULL, colour_argb INTEGER);
CREATE TABLE transaction_tags (transaction_id TEXT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(transaction_id, tag_id));
CREATE TABLE attachments (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), transaction_id TEXT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, display_name TEXT NOT NULL, mime_type TEXT NOT NULL, vault_relative_path TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE budget_definitions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, amount_minor INTEGER NOT NULL, currency_code TEXT NOT NULL, scope_type TEXT NOT NULL, period_type TEXT NOT NULL, start_local_date TEXT NOT NULL, interval_count INTEGER NOT NULL DEFAULT 1, carry_mode TEXT NOT NULL, alert_percent INTEGER, effective_from TEXT NOT NULL, effective_until TEXT, is_paused INTEGER NOT NULL DEFAULT 0);
CREATE TABLE budget_scope_categories (budget_definition_id TEXT NOT NULL REFERENCES budget_definitions(id) ON DELETE CASCADE, category_id TEXT NOT NULL REFERENCES categories(id), PRIMARY KEY(budget_definition_id, category_id));
CREATE TABLE budget_periods (id TEXT PRIMARY KEY, budget_definition_id TEXT NOT NULL REFERENCES budget_definitions(id) ON DELETE CASCADE, period_start TEXT NOT NULL, period_end TEXT NOT NULL, limit_minor INTEGER NOT NULL, carry_in_minor INTEGER NOT NULL DEFAULT 0, closed_at INTEGER, UNIQUE(budget_definition_id, period_start, period_end));
CREATE TABLE saved_filters (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL, filter_json TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE backup_history (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), created_at INTEGER NOT NULL, destination_uri TEXT, package_name TEXT NOT NULL, size_bytes INTEGER, sha256 TEXT, status TEXT NOT NULL, record_counts_json TEXT, error_code TEXT);
CREATE TABLE import_jobs (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), source_uri TEXT NOT NULL, format TEXT NOT NULL, started_at INTEGER NOT NULL, completed_at INTEGER, status TEXT NOT NULL, summary_json TEXT, error_log_path TEXT);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, timestamp INTEGER NOT NULL, metadata_json TEXT);
CREATE INDEX idx_tx_profile_date ON transactions(profile_id, local_date DESC);
CREATE INDEX idx_tx_account_date ON transactions(account_id, local_date DESC);
CREATE INDEX idx_tx_category_date ON transactions(category_id, local_date DESC);
CREATE INDEX idx_tx_merchant ON transactions(merchant_id);
CREATE INDEX idx_budget_period ON budget_periods(budget_definition_id, period_start);
CREATE INDEX idx_attachment_tx ON attachments(transaction_id);
